INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9016, 25969, 'tt0112368', NULL, 'Angus', 'Angus', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/x1Py4TB8Y0Wx9IZ62derpSDqwjd.jpg', 'https://image.tmdb.org/t/p/original/qGW0LutVJfqEkBGooJj3w9ngLV8.jpg', 'Angus is a large, pathetic 14-year-old whose thoughts are most often filled with the image of only one girl, Melissa Lefevre. Angus is shy and thinks that he has no chance of ever ''getting'' her. Being especially uncool, he is incredibly surprised (along with the rest of the school) that he is chosen to dance with her at the Winter Ball. The only one not surprised is the cool kid who set him up to fail, but Angus'' best friend is going to help him win the heart of Melissa by developing a new look for him', NULL, NULL, 2.4333, 6.6, 0, 11.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9017, 10013, 'tt0091738', NULL, 'Peggy Sue Got Married', 'Peggy Sue Got Married', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/tfuQcvQmURiMqB2VPwytU3cPpEm.jpg', 'https://image.tmdb.org/t/p/original/xCtyGEn5VGMKV7S9xRbQJyojgYf.jpg', 'At her 25th high school reunion, Peggy Sue faints and awakens in 1960—back in her senior year, before her marriage and all her regrets. Given a second chance to relive her youth, she must decide whether to change the choices that shaped her life or embrace the past that made her who she is.', NULL, NULL, 3.7098, 6.117, 0, 10.06, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9018, 3845, 'tt0070992', NULL, 'Happy Days', 'Happy Days', 'tv', 1974, 'https://image.tmdb.org/t/p/w500/sepIwNPCEhkKvFOQSjXK6tekkjR.jpg', 'https://image.tmdb.org/t/p/original/lyAx1XlcrPaenfwvSYnOl4h4WMk.jpg', 'In 1950s Milwaukee the Cunningham family must contend with Fonzie, a motorcycle riding Casanova.', NULL, NULL, 32.4619, 7.635, 0, 13.025, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9019, 15489, 'tt0184907', NULL, 'Snow Day', 'Snow Day', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/myTnHKy178rrd1oUG3GkEvc641G.jpg', 'https://image.tmdb.org/t/p/original/1pRWwg3MkUpUvbsFOgUTEvMaNvA.jpg', 'When an entire town in upstate New York is closed down by an unexpected snowfall, a "snow day" begins when a group of elementary school kids, led by Natalie Brandston, try to ensure that the schools stay closed by stopping a mechanical snowplow driver by trying to hijack his plow truck. Meanwhile, Natalie''s big brother Hal is using this day to try to win the affections of Claire Bonner, the most popular girl in his high school, while Hal and Natalie''s father Tom, a TV meteorologist, faces off against a rival meteorologist for weather coverage of the day''s events.', NULL, NULL, 2.8561, 5.112, 0, 10.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9020, 10050, 'tt0192071', NULL, 'Get Over It', 'Get Over It', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/hS1jjzTe4P8GMWGnvca7HIndPEX.jpg', 'https://image.tmdb.org/t/p/original/saQxwnIr4ftRmFpJeV9DQI1lsWd.jpg', 'When Berke Landers, a popular high school basketball star, gets dumped by his life-long girlfriend, Allison, he soon begins to lose it. But with the help of his best friend Felix''s sister Kelly, he follows his ex into the school''s spring musical. Thus ensues a love triangle loosely based upon Shakespeare''s "A Midsummer Night''s Dream", where Berke is only to find himself getting over Allison and beginning to fall for Kelly.', NULL, NULL, 3.5563, 5.564, 0, 10.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9021, 24153, 'tt0077280', NULL, 'The Buddy Holly Story', 'The Buddy Holly Story', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/4Zu9YdN5O4jnXJmqBMHckkKpJ2S.jpg', 'https://image.tmdb.org/t/p/original/tdpHGUxipEmJZvtEmTCcmpE2HMp.jpg', 'A chronicle of the rise and brief career of rock ''n'' roll star Buddy Holly, who aspires to play music the way he wants it to sound. Holly and his band, the Crickets, are first invited to record in Nashville, where they encounter creative differences with the producing staff. Later they play a major booking at the Apollo Theater, scheduled there under the mistaken assumption that they''re a black band. Holly''s career eventually goes solo -- until the tragic day the music dies.', NULL, NULL, 2.4008, 7.174, 0, 10.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9022, 19067, 'tt0075968', NULL, 'The Duellists', 'The Duellists', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/nqjMYlUXnmmO8Jqucow4nj9alE5.jpg', 'https://image.tmdb.org/t/p/original/xyVURBvbRIzsGJlD0h8vybkXjLs.jpg', 'In 1800, as Napoleon Bonaparte rises to power in France, a rivalry erupts between Armand and Gabriel, two lieutenants in the French Army, over a perceived insult. For over a decade, they engage in a series of duels amidst larger conflicts, including the failed French invasion of Russia in 1812, and shifts in the political and social systems of Europe.', NULL, NULL, 4.993, 7.245, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9023, 96721, 'tt1979320', NULL, 'Rush', 'Rush', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/95BDrWmcfJDEa2WCfjmLgi67jhi.jpg', 'https://image.tmdb.org/t/p/original/D3eDUNEzJPBDG3TCJcR7RyRgTA.jpg', 'In the 1970s, a rivalry propels race car drivers Niki Lauda and James Hunt to fame and glory — until a horrible accident threatens to end it all.', NULL, NULL, 11.9303, 7.744, 0, 1.04, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9024, 9631, 'tt0120768', NULL, 'The Negotiator', 'The Negotiator', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/dUMHEymATOGbs2K3E4dmNSVBgFQ.jpg', 'https://image.tmdb.org/t/p/original/y4TbQOC9DCzZop9HwKuX73rKbYO.jpg', 'The police try to arrest expert hostage negotiator Danny Roman, who insists he''s being framed for his partner''s murder in what he believes is an elaborate conspiracy. Thinking there''s evidence in the Internal Affairs offices that might clear him, he takes everyone in the office hostage and demands that another well-known negotiator be brought in to handle the situation and secretly investigate the conspiracy.', NULL, NULL, 8.3955, 7.111, 0, 2.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9025, 1565344, 'tt38706617', NULL, 'Parking', 'Parking', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/oNxANEMPx3sbj6BY9VtZxrXCMDF.jpg', 'https://image.tmdb.org/t/p/original/9LXVLQrTedD5xpaIo4KDlVhEjyz.jpg', 'Mateo, a criminal under house arrest, works at a parking garage in downtown Buenos Aires and plans to escape. His routine is disrupted when Lara pays for an overnight stay and minutes later an armed man breaks into the place. Both witness a murder that triggers a deadly chase through ramps and levels of the building, forcing them to fight against time and criminals to escape alive from the labyrinth.', NULL, NULL, 2.175, 4.0, 0, 2.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
