INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9040, 146075, 'tt0048572', NULL, 'Rio, 100 Degrees F°', 'Rio, 40 Graus', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/bgNYhX1hFFhp4IMjcVlIWomtipl.jpg', 'https://image.tmdb.org/t/p/original/chzvzxHOFhs0tBkbDfoE6exchBP.jpg', 'On a scorching summer day in Rio de Janeiro, five impoverished black boys venture out of their favela to peddle peanuts throughout the bustling city. As they navigate the various districts of Rio, they bear witness to a series of unfortunate events and encounters, unfolding a vivid tapestry of urban life in Rio de Janeiro during that period. These true misadventures shed light on the gritty reality of the city, unveiling its vibrant urban tapestry.', NULL, NULL, 0.9658, 7.061, 0, 8.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9041, 39393, 'tt1174691', NULL, 'Once Upon a Time in Rio', 'Era uma Vez...', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/iw5KVyuWtRK0mT7HIYpWzVFOdUn.jpg', 'https://image.tmdb.org/t/p/original/9PJc8wYqp2Z484pBRnoDaIZSNTm.jpg', 'Situated just above the awe-inspiring Ipanema beach in Rio is the Cantagalo slum. Every day, floods of Cantagalo residents make their way down the mountain, only to disappear into their surroundings as part of the invisible working-class that cleans apartments, works in restaurants, and sells food along the scenic, sun-drenched shores. Young Dé (Thiago Martins) is just such a man. Dé lives with his mother Bernadette (Cyria Coentro) in a cramped Cantagalo apartment, selling hot dogs on the beach in order to make the rent. His brother Beto was killed when Dé was just a young boy, and his adopted brother Carlão (Rocco Pitanga) has been jailed for a robbery that he didn''t commit. One day, while working on the beach, Dé meets Nina (Vitória Frate). Nina is the only child of a successful lawyer named Evandro (Paulo César Grande), who''s none to happy to discover that his daughter is dating a member of the lower class. How...', NULL, NULL, 1.3342, 7.397, 0, 8.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9042, 1212121, 'tt35301431', NULL, 'Latin Blood – The Ballad of Ney Matogrosso', 'Homem com H', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/vWhWbA4w4Pn8WXo3C7VTOzCattZ.jpg', 'https://image.tmdb.org/t/p/original/cSlSMAN2iWwmDlEOOUt8PfOIaQa.jpg', 'From a repressive childhood to artistic revolution, Ney Matogrosso transforms Brazil''s stages — and himself — through music, creativity and inner fire.', NULL, NULL, 2.0043, 8.051, 0, 4.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9043, 227975, 'tt2199543', NULL, 'Futuro Beach', 'Praia do Futuro', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/lologg70UiUMok8ijdSfDzBwR0N.jpg', 'https://image.tmdb.org/t/p/original/AuzyTuRHzmS78cP6pR9SgDQC6ys.jpg', 'Donato fails in his attempt to save a drowning man, and meets one of the man''s friends. He decides to start his life over, but pieces of his past keep coming after him.', NULL, NULL, 1.507, 6.5, 0, 6.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9044, 11418, 'tt0089670', NULL, 'National Lampoon''s European Vacation', 'National Lampoon''s European Vacation', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/hZL7g1oSDrA0Lx5wcHpEl99MYKi.jpg', 'https://image.tmdb.org/t/p/original/2vwdO2ist8YgKg60p4N7S8Hwd0A.jpg', 'The Griswolds win a vacation to Europe on a game show, and so pack their bags for the continent. They do their best to catch the flavor of Europe, but they just don''t know how to be be good tourists. Besides, they have trouble taking holidays in countries where they CAN speak the language.', NULL, NULL, 5.9539, 6.158, 0, 8.655, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9045, 62957, 'tt1177054', NULL, 'Der Bergdoktor', 'Der Bergdoktor', 'tv', 2008, 'https://image.tmdb.org/t/p/w500/4sQVzAPWG2QfJOITaayRnxKjXuw.jpg', 'https://image.tmdb.org/t/p/original/4XsXz6gGD2WcdMgGz4RUtWqgwA0.jpg', 'A medic lives with his small and strange family between the mountains and every episode he comes across a situation with not only his patients but also his family and friends.', NULL, NULL, 27.6879, 5.759, 0, 9.125, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9046, 153282, 'tt11269100', NULL, 'Sisi', 'Sisi', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/eR54VLAOWFOR9F9T61yOZJiHnEQ.jpg', 'https://image.tmdb.org/t/p/original/9Ms5Tpm7hyvDfqN9w2apky22CEJ.jpg', '"Sisi" follows the extraordinary life of Empress Elisabeth of Austria. Modern, honest, and authentic. Told from the perspective of her closest confidants, the series takes a new look at the empress'' life and reveals a multi-layered woman.', NULL, NULL, 12.3475, 7.4, 0, 8.565, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
