INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9048, 5925, 'tt0057115', NULL, 'The Great Escape', 'The Great Escape', 'movie', 1963, 'https://image.tmdb.org/t/p/w500/gBH4H8UMFxl139HaLz6lRuvsel8.jpg', 'https://image.tmdb.org/t/p/original/lb87H6BFXXKMJlUnDHvPOMGfh8z.jpg', 'The Nazis, exasperated at the number of escapes from their prison camps by a relatively small number of Allied prisoners, relocate them to a high-security ''escape-proof'' camp to sit out the remainder of the war. Undaunted, the prisoners plan one of the most ambitious escape attempts of World War II. Based on a true story.', NULL, NULL, 9.6871, 7.9, 0, 4.52, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9049, 75214, 'tt7078180', NULL, 'Violet Evergarden', 'ヴァイオレット・エヴァーガーデン', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/61EwFPqc0r1uJo6la49J55F8bQ8.jpg', 'https://image.tmdb.org/t/p/original/2e2AEk7Jmn8CztM62hoUyEEWw0B.jpg', 'The war is over, and Violet Evergarden needs a job. Scarred and emotionless, she takes a job as a letter writer to understand herself and her past.', NULL, NULL, 16.2682, 8.502, 0, 4.51, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9050, 31102, 'tt0054195', NULL, 'Pollyanna', 'Pollyanna', 'movie', 1960, 'https://image.tmdb.org/t/p/w500/9lWkRXg35SjUZXLr10ez8DERvRv.jpg', 'https://image.tmdb.org/t/p/original/daAGNEXy8VC0VXWG1QZCrZhUqKJ.jpg', 'A young girl comes to an embittered town and confronts its attitude with her determination to see the best in life.', NULL, NULL, 2.6377, 6.96, 0, 5.54, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9051, 48661, 'tt0304072', NULL, 'The Dog of Flanders', 'フランダースの犬', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/iQL9qWTfaCCSfnyqsFjwdhEyyP2.jpg', 'https://image.tmdb.org/t/p/original/iQCg1oPi9ZX2UIFH1ey9BoijM3J.jpg', 'Nello Tarth is a poor but happy orphan who lives with his grandfather Jehan and his dog Patrasche in a little village near Antwerp. He spends his days drawing and delivering milk. When Nello decides to enter an art contest, he experiences firsthand the ignorance and cruelty of the villagers of the town. Nonetheless, with the help of his beloved dog, Nello perseveres to achieve his dream.', NULL, NULL, 1.5197, 7.538, 0, 6.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9052, 424694, 'tt1727824', NULL, 'Bohemian Rhapsody', 'Bohemian Rhapsody', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', 'https://image.tmdb.org/t/p/original/dcvbs8z0GEXslC1kCT77x19XDeR.jpg', 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock ''n'' roll band Queen in 1970. Hit songs become instant classics. When Mercury''s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.', NULL, NULL, 14.6927, 7.954, 0, 2.095, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9053, 614934, 'tt3704428', NULL, 'Elvis', 'Elvis', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/qBOKWqAFbveZ4ryjJJwbie6tXkQ.jpg', 'https://image.tmdb.org/t/p/original/rLo9T9jEg67UZPq3midjLnTUYYi.jpg', 'The life story of Elvis Presley as seen through the complicated relationship with his enigmatic manager, Colonel Tom Parker.', NULL, NULL, 8.2909, 7.45, 0, 1.17, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9054, 74239, 'tt0117028', NULL, 'Message to Love - The Isle of Wight Festival', 'Message to Love - The Isle of Wight Festival', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/umFPPFzQ5JPvCe6aCrpNUmbhNK4.jpg', 'https://image.tmdb.org/t/p/original/v5aHmQvWYP9TfEEFe1A7Y5zSlSn.jpg', 'In August 1970, 600,000 fans flocked to the Isle of Wight to witness the third and final festival to be held on the island. Besides the music, they also got a look at the greed, cynicism and corruption that would plague the music industry for years to come. They also witnessed the final, drugged out performance of Jimi Hendrix in England just two weeks before he would meet a tragic death. When it all was over, the fans view of rock and roll was never the same.', NULL, NULL, 0.8868, 6.808, 0, 1.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9055, 132, 'tt0065780', NULL, 'Gimme Shelter', 'Gimme Shelter', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/7lWFVDYyeft9WbglHGEBUl9OLFu.jpg', 'https://image.tmdb.org/t/p/original/c4Chm8w7AsekIkPb6KSxUxCzXq2.jpg', 'A detailed chronicle of the famous 1969 tour of the United States by the British rock band The Rolling Stones, which culminated with the disastrous and tragic concert held on December 6 at the Altamont Speedway Free Festival, an event of historical significance, as it marked the end of an era: the generation of peace and love suddenly became the generation of disillusionment.', NULL, NULL, 2.1334, 7.335, 0, 1.06, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9056, 13595, 'tt0109068', NULL, 'Airheads', 'Airheads', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/4xPG8pPMyeoec48gKWbbC85EC8j.jpg', 'https://image.tmdb.org/t/p/original/tkMVZc8JbOtRhzOsxph9jDVquq9.jpg', 'The Lone Rangers have heavy-metal dreams and a single demo tape they can''t get anyone to play. The solution: Hijack an FM rock radio station and hold the deejays hostage until they agree to broadcast the band''s tape.', NULL, NULL, 3.4889, 6.211, 0, 1.05, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9057, 25771, 'tt0069090', NULL, 'Pink Floyd: Live at Pompeii', 'Pink Floyd: Live at Pompeii', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/bxjgbHH14nEMx3YtFDLJ04omQhH.jpg', 'https://image.tmdb.org/t/p/original/jqcKHIV4sCzvCffzQmuOJfG4jiQ.jpg', 'British progressive rock band Pink Floyd perform at the ancient Roman Amphitheatre in the ruins of Pompeii, Italy in 1971. Although the band perform a typical live set from the era, there is no audience beyond the basic film crew.', NULL, NULL, 2.5727, 8.037, 0, 1.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9058, 26028, 'tt0093312', NULL, 'Jimi Plays Monterey', 'Jimi Plays Monterey', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/lpO4JSRMzGH1A8KbXhyDFvlNe3D.jpg', 'https://image.tmdb.org/t/p/original/mlo31XZhJ9mEgS7Is6L3cz75UyQ.jpg', 'Jimi Hendrix''s debut American set at 1967''s Monterey Pop Festival is generally considered one of the most radical and legendary live shows ever. Virtually unknown to American audiences at the time, even though he was already an established entity in the UK, Hendrix and his two-piece Experience explode on stage, ripping through blues classics "Rock Me Baby" and Howlin'' Wolf''s "Killing Floor," interpreting and electrifying Bob Dylan''s "Like a Rolling Stone," debuting songs from his yet-to-be-released first album and closing with the now historic sacrificing/burning of his guitar during an unhinged version of "Wild Thing" that even its writer Chip Taylor would never have imagined. Hendrix uses feedback and distortion to enhance the songs in whisper-to-scream intensity, blazing territory that had not been previously explored with as much soul-frazzled power.', NULL, NULL, 1.5294, 7.5, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9059, 29628, 'tt0085551', NULL, 'Get Crazy', 'Get Crazy', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/biOonZmJloMVqdz4g0ghFEnDtEr.jpg', 'https://image.tmdb.org/t/p/original/vft58FknLvj4k4uYCQOCVLvFr1A.jpg', 'Mega-promoter Colin Beverly plans to sabotage the New Year''s 1983 concert of small-time operator Max Wolfe. Wolfe''s assistants Neil Allen and Willie Loman find romance while trying to save the drugs, violence, and rock and roll from Beverly''s schemes.', NULL, NULL, 1.7086, 6.115, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9060, 18094, 'tt1157605', NULL, 'Anvil! The Story of Anvil', 'Anvil! The Story of Anvil', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/rDrMuFaWBKwjwEnw4C06Sm97huY.jpg', 'https://image.tmdb.org/t/p/original/2AMk0Df2Lr0WtFDHGsEo1UE8IHW.jpg', 'At 14, best friends Robb Reiner and Lips made a pact to rock together forever. Their band, Anvil, hailed as the "demi-gods of Canadian metal" influenced a musical generation that includes Metallica, Slayer, and Anthrax. Following a calamitous European tour, Lips and Robb, now in their fifties, set off to record their 13th album in one last attempt to fulfill their boyhood dreams.', NULL, NULL, 1.6723, 7.583, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9061, 6575, 'tt0841046', NULL, 'Walk Hard: The Dewey Cox Story', 'Walk Hard: The Dewey Cox Story', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/Aa1IQ4Cuin3d7qIahvPheMmR4E5.jpg', 'https://image.tmdb.org/t/p/original/axg73mVxiZcE9Pzynu2uj1TYIgj.jpg', 'Following a childhood tragedy, Dewey Cox follows a long and winding road to music stardom. Dewey perseveres through changing musical styles, an addiction to nearly every drug known and bouts of uncontrollable rage.', NULL, NULL, 3.9035, 6.607, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
