INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9115, 42943, 'tt0026276', NULL, 'The Devil Is a Woman', 'The Devil Is a Woman', 'movie', 1935, 'https://image.tmdb.org/t/p/w500/cc5HUdBbnMSST78sfujsOU4T0Vk.jpg', 'https://image.tmdb.org/t/p/original/1nwI1v3cWMpqkzJLCJrdjveyPU2.jpg', 'In the carnival in Spain in the beginning of the Twentieth Century, the exiled republican Antonio Galvan comes from Paris masquerade to enjoy the party and visit his friend Capt. Don Pasqual ''Pasqualito'' Costelar. However, he flirts with the mysterious Concha Perez and they schedule to meet each other later. When Antonio meets Pasqualito, his old friend discloses his frustrated relationship with the promiscuous Concha and her greedy mother and how his life was ruined by his obsession for the beautiful demimondaine. Pasqualito makes Antonio promise that he would not see Concha. However, when Antonio meets Concha, she seduces him and the long friendship between Antonio and Pasqualito is disrupted', NULL, NULL, 1.3355, 6.3, 0, 1.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
