INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9122, 5966, 'tt0343135', NULL, 'Along Came Polly', 'Along Came Polly', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/7Tp16THdpHkMrqgoiDresDz9CWL.jpg', 'https://image.tmdb.org/t/p/original/d0oHN3xA6TxOvADW64OiyYFpLOf.jpg', 'Reuben Feffer is a guy who''s spent his entire life playing it safe. Polly Prince is irresistible as a free-spirit who lives for the thrill of the moment. When these two comically mismatched souls collide, Reuben''s world is turned upside down, as he makes an uproarious attempt to change his life from middle-of-the-road to totally-out-there.', NULL, NULL, 8.5371, 6.032, 0, 1.17, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
