INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9124, 12658, 'tt0244970', NULL, 'Someone Like You...', 'Someone Like You...', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/9cMkJSl2TI4xe8lKNFduinafKpe.jpg', 'https://image.tmdb.org/t/p/original/fRNNl8iLc4mpWy1C2JDIJdJxHQZ.jpg', 'Jane Goodale has everything going for her. She''s a producer on a popular daytime talk show, and is in a hot romance with the show''s dashing executive producer Ray. But when the relationship goes terribly awry, Jane begins an extensive study of the male animal, including her womanizing roommate Eddie. Jane puts her studies and romantic misadventure to use as a pseudonymous sex columnist -- and becomes a sensation.', NULL, NULL, 4.4519, 5.956, 0, 1.11, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9125, 193610, 'tt2203939', NULL, 'The Other Woman', 'The Other Woman', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/yHnbb6z8REuFIyBLT2Nj3MX54dY.jpg', 'https://image.tmdb.org/t/p/original/w5pNa5J3PtjY0d1DbFYOoW8Ftaj.jpg', 'After discovering her boyfriend is married, Carly soon meets the wife he''s been cheating on. And when yet another affair is discovered, all three women team up to plot mutual revenge on the three-timing SOB.', NULL, NULL, 7.5625, 6.423, 0, 1.44, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9126, 18520, 'tt1280822', NULL, 'Drop Dead Diva', 'Drop Dead Diva', 'tv', 2009, 'https://image.tmdb.org/t/p/w500/fbu2O3hbU1ZROpjU01YCAMLz1sR.jpg', 'https://image.tmdb.org/t/p/original/cfJoy6gW8XQytBRktBqYw5cXibt.jpg', 'A shallow model suddenly dies in an accident only to find her soul resurfacing in the body of a brilliant, plus-sized attorney.', NULL, NULL, 20.7908, 7.735, 0, 1.44, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9127, 26103, 'tt3597470', NULL, 'Hindsight', 'Hindsight', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/wxpXx2cv85IzAFdp5Aapy46yNGY.jpg', 'https://image.tmdb.org/t/p/original/ufSBncIKII6QNfuHHp0VpQ9znj7.jpg', 'The series begins with Becca on the eve of her second wedding. It all seems perfect this time around, but she is still plagued by doubt. What if she could fix everything, and make the ''right'' choices this time? Becca finds herself thinking about her former best friend Lolly, with whom she had a falling out many years ago. If only she could talk to her once again… Suddenly, after a freakish elevator ride, Becca gets the opportunity to do just that as she wakes up in New York City on the morning of her first wedding day in 1995. She''s about to marry Sean, a bad-boy artist who is all wrong for her – and she knows her first move must be to reconnect with Lolly to re-live that day. Can she ''make it right'' by living her life all over while re-adapting to life in New York City in the 90''s – a time of smoking in bars, carrying pagers, having an AOL email address? Becca will soon discover there''s no sure-fire way to make the right choices in life – even knowing everything she thinks she knows now.', NULL, NULL, 2.5288, 6.457, 0, 1.05, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9128, 3461, 'tt0118303', NULL, 'Dharma & Greg', 'Dharma & Greg', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/zmafXjaQphnyHZ8oF3Q51DDIRWZ.jpg', 'https://image.tmdb.org/t/p/original/5PNMnVfIol6CCfrU39hE9azZiIn.jpg', 'Dharma & Greg is an American television sitcom that aired from September 24, 1997, to April 30, 2002.

It stars Jenna Elfman and Thomas Gibson as Dharma and Greg Montgomery, a couple who got married on their first date despite being complete opposites. The series is co-produced by Chuck Lorre Productions, More-Medavoy Productions and 4 to 6 Foot Productions in association with 20th Century Fox Television for ABC. The show''s theme song was written and performed by composer Dennis C. Brown.

Created by executive producers Dottie Dartland and Chuck Lorre, the comedy took much of its inspiration from so-called culture-clash "fish out of water" situations. The show earned eight Golden Globe nominations, six Emmy Award nominations, and six Satellite Awards nominations. Elfman earned a Golden Globe in 1999 for Best Actress.', NULL, NULL, 13.9187, 6.392, 0, 1.07, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
