INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9139, 312831, 'tt2474976', NULL, 'The Hallow', 'The Hallow', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/sOT4KqFPlvxTeEwyHOcn8agJnsI.jpg', 'https://image.tmdb.org/t/p/original/x3qfexS225RyoOUz807q5KVFQwp.jpg', 'Deep within the darkness of secluded forest land in rural Ireland dwells an ancient evil. Feared by the nearby superstitious villagers as cursed creatures who prey upon the lost, their secrets have been kept from civilization and remain on their hallowed ground. But when a conservationist from London moves in with his wife and infant child in order to survey the land for future construction, his actions unwittingly disturb the horde of demonic forces. Alone in a remote wilderness, he must now ensure his family''s survival from their relentless attacks.', NULL, NULL, 3.212, 5.739, 0, 1.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
