INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9141, NULL, NULL, 7603, 'Hellblade: Senua''s Sacrifice', 'Hellblade: Senua''s Sacrifice', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l7l.jpg', NULL, 'Hellblade: Senua''s Sacrifice is a single-player action-adventure game set in a dark fantasy world inspired by Norse mythology and Celtic culture. Players control Senua, a Pict warrior who journeys into the Norse underworld to rescue the soul of her dead lover from the goddess Hela. The game blends melee combat, puzzle solving, and psychological horror, with Senua''s psychosis shaping how the world is perceived, including voices that provide guidance or attempt to mislead the player.

The game was developed by a team of around twenty people and features no heads-up display or tutorials. Instead, audio cues from voices in Senua''s head guide the player through combat and environmental challenges. The portrayal of psychosis was developed in collaboration with neuroscientists and people who experience the condition.', 'https://www.igdb.com/games/hellblade-senuas-sacrifice', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
