INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9222, 41852, 'tt0116275', NULL, 'A Family Thing', 'A Family Thing', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/1IHxwmguaeytGo6m0wZaS0s3fP.jpg', 'https://image.tmdb.org/t/p/original/ypjHHnZuPn7A1Euqi1onU32Ejgs.jpg', 'Earl Pilcher Jr. runs an equipment rental outfit in Arkansas, lives with his wife and kids and parents, and rarely takes off his gimme cap. His mother dies, leaving a letter explaining he''s not her natural son, but the son of a Black woman who died in childbirth; plus, he has a half brother Ray, in Chicago, she wants him to visit. Earl makes the trip, initially receiving a cold welcome from Ray and Ray''s son, Virgil. His birth mother''s sister, Aunt T., an aged and blind matriarch, takes Earl in tow and insists that the family open up to him.', NULL, NULL, 1.9409, 6.546, 0, 41.04, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
