INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9241, 39962, 'tt0374262', NULL, 'Tamala 2010: A Punk Cat in Space', 'TAMALA2010 a punk cat in space', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/hRH72j6JzWkiOlI2yiW7E9BCkQ1.jpg', 'https://image.tmdb.org/t/p/original/mCcG1ZVH9DnHRC5cwhrCbUiNQp3.jpg', 'Tamala is a cat living on Planet Cat Earth in the Feline Galaxy. In attempt to leave the Feline Galaxy, which is practically owned by a mega corporation called Catty & Co., she crashes on the violence-ridden Planet Q where she meets Michelangelo. Together they have fun, while Tamala seaches for her connections to Catty & Co. and her mysterious homeworld Orion.', NULL, NULL, 1.3794, 6.407, 0, 10.03, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9242, 247029, 'tt2206068', NULL, 'Superflat Monogram', 'Superflat Monogram', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/4u3KomeLDVr0xYJhGIqjFzaMuC2.jpg', 'https://image.tmdb.org/t/p/original/sDG5pFg4IQjxMSKIXNtIJ4Y1imD.jpg', 'While waiting to meet her friends outside of a Louis Vuitton store, Aya''s cell phone is eaten by the LV Panda, who then promptly swallows Aya - but the inside of his stomach is gateway to a psychadelic wonderland. Based on characters created by famed superflat artist Takashi Murakami.', NULL, NULL, 0.785, 5.4, 0, 10.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9243, 40123, 'tt0962762', NULL, 'Genius Party', 'Genius Party', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/e0jqLkjEOtfRhugXs84tfZtT9i8.jpg', 'https://image.tmdb.org/t/p/original/5HBrONjnQ4dDuOnNOfZkmj0B9se.jpg', 'The seven short films making up GENIUS PARTY couldn’t be more diverse, linked only by a high standard of quality and inspiration. Atsuko Fukushima’s intro piece is a fantastic abstraction to soak up with the eyes. Masaaki Yuasa, of MIND GAME and CAT SOUP fame, brings his distinctive and deceptively simple graphic style and dream-state logic to the table with “Happy Machine,” his spin on a child’s earliest year. Shinji Kimura’s spookier “Deathtic 4,” meanwhile, seems to tap into the creepier corners of a child’s imagination and open up a toybox full of dark delights. Hideki Futamura’s “Limit Cycle” conjures up a vision of virtual reality, while Yuji Fukuyama’s "Doorbell" and "Baby Blue" by Shinichiro Watanabe use understated realism for very surreal purposes. And Shoji Kawamori, with “Shanghai Dragon,” takes the tropes and conventions of traditional anime out for very fun joyride.', NULL, NULL, 2.1123, 6.508, 0, 10.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9244, 121072, 'tt2215676', NULL, 'The Warped Forest', 'あさっての森', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/uTP58pEXbjLr43NAa1FN4da7a5R.jpg', 'https://image.tmdb.org/t/p/original/sPbqfEx2L15wq1hmdhYngUIabUY.jpg', 'Settle into your chair and be transported to a place both familiar and alien; where a giant shop-girl can barely fit in her store, there''s a weird green pod in every bedroom, and terrifying wood nymphs provide a heartbroken woman with the anatomically correct fruit everyone seems to covet. In the end we are left, like Alice, with the Red King''s conundrum: are we dreaming them or are they dreaming us?', NULL, NULL, 1.4917, 5.2, 0, 9.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9245, 14554, 'tt0047849', NULL, 'Bad Day at Black Rock', 'Bad Day at Black Rock', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/8EnhHjU0DyCckmZRtn46s3WXeEf.jpg', 'https://image.tmdb.org/t/p/original/tQv32m6pufbJT2rKuKDzt0kVynQ.jpg', 'One-armed war veteran John J. Macreedy steps off a train at the sleepy little town of Black Rock.  Once there, he begins to unravel a web of lies, secrecy, and murder.', NULL, NULL, 3.676, 7.292, 0, 1.04, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
