INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9249, 2955, 'tt0315701', NULL, 'Push, Nevada', 'Push, Nevada', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/xgT9e4nYQjUj4ImggCPbL0QHCfd.jpg', 'https://image.tmdb.org/t/p/original/l0b3v6TPRHAPhvCi3I9axBMCDxR.jpg', 'A mild-mannered IRS agent travels to a remote desert region in search of missing money and stumbles into a strange small town where mystery, danger, and peculiar characters lurk around every off-kilter corner. Everyone in Push has a secret, but no one is talking … unless they''re telling our man to get out of town, fast.', NULL, NULL, 3.4939, 5.357, 0, 1.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9250, 2290, 'tt0374455', NULL, 'Stargate Atlantis', 'Stargate Atlantis', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/l0JYr2iqwId6VOmCV8dHzlIM6Wd.jpg', 'https://image.tmdb.org/t/p/original/SLAPI1h9SWBMLTCO8ULvTGiP9G.jpg', 'With the Ancients'' city of Atlantis discovered in the Pegasus Galaxy by Stargate Command, Dr. Elizabeth Weir and Major Sheppard lead a scientific expedition to the ancient abandoned city. Once there, the team not only find themselves unable to contact Earth, but their explorations unexpectedly reawaken the Ancients'' deadly enemies, The Wraith, who hunger for this new prey. Now with the help of newfound local allies like Teyla Emmagan, the Atlantis Team sets about to uncover their new home''s secrets even as their war of survival against the Wraith begins.', NULL, NULL, 43.0958, 8.036, 0, 1.05, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9251, 202208, 'tt20285780', NULL, 'The Artful Dodger', 'The Artful Dodger', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/lcyax0pIH6vZWbho2hxsMTt9KpN.jpg', 'https://image.tmdb.org/t/p/original/8SqmduaPoPvSpqPUEw0YNXvJoQj.jpg', 'It''s a tale of reinvention, betrayal, redemption, and love with a twist. Jack Dawkins is The Artful Dodger, whose pickpocketing fingers have become the skilled hands of a surgeon. He is torn between an impossible love and the criminal underworld he secretly craves. This will require Artfulness.', NULL, NULL, 15.3907, 8.1, 0, 1.05, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9252, 894078, 'tt16118378', NULL, 'Detective Dee and The Red Eye', 'Detective Dee and The Red Eye', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/p7sX07EAaqZ1GeCw0vo3gkkiHQJ.jpg', 'https://image.tmdb.org/t/p/original/bkKcSWzuzY8ozCaKTE7g1GAD8GW.jpg', 'On the occasion of the birthday feast of Queen Wu Zetian, it was suddenly reported that the "red-eyed monster" was committing a chaotic case, and Wu Zetian ordered Di Renjie to supervise the case. Di Renjie and his apprentice Chen Jiangqiao came to Fangzhou to investigate the case, and chanced upon Shen Qingqing, who was also investigating the case. Through the investigation of the case, the trio gradually approached the truth behind the "red-eyed monster", which led to a series of serial incidents. In the process of dealing with this series of incidents, Di Renjie was upright, putting the common people of Li people first, and expressing a sense of responsibility and mission that "everyone is responsible for the rise and fall of the world", and finally successfully solved the mystery.', NULL, NULL, 1.8718, 5.0, 0, 3.02, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
