INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9263, NULL, NULL, 19560, 'God of War', 'God of War', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkt6.jpg', NULL, 'God of War is the sequel to God of War III as well as a continuation of the canon God of War chronology. Unlike previous installments, this game focuses on Norse mythology and follows an older and more seasoned Kratos and his son Atreus in the years since the third game. It is in this harsh, unforgiving world that he must fight to survive… and teach his son to do the same.', 'https://www.igdb.com/games/god-of-war--1', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
