INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9288, 190847, 'tt1709143', NULL, 'The Last Days on Mars', 'The Last Days on Mars', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/kxcQkAhpn8cvJTsU8PXblI5Qq8F.jpg', 'https://image.tmdb.org/t/p/original/zZUuNeCzA5W6YJweyFLxBN6xTHx.jpg', 'On the last day of the first manned mission to Mars, a crew member of Tantalus Base believes he has made an astounding discovery – fossilized evidence of bacterial life. Unwilling to let the relief crew claim all the glory, he disobeys orders to pack up and goes out on an unauthorized expedition to collect further samples. But a routine excavation turns to disaster when the porous ground collapses and he falls into a deep crevice. His devastated colleagues attempt to recover his body. However, when another vanishes, they start to suspect that the life-form they have discovered is not without danger.', NULL, NULL, 4.0831, 5.514, 0, 10.01, '2026-08-11 02:46:38', '2026-08-11 02:46:38');
