UPDATE "recommendations" SET "tmdb_id"=6114, "imdb_id"='tt0103874', "igdb_id"=NULL, "title"='Bram Stoker''s Dracula', "original_title"='Bram Stoker''s Dracula', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/jSxCIZXudp5q8wQO8VERGX8hRAl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/88S6EYQBVyQktDfSqsB33I169jN.jpg', "overview"='Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.4789, "vote_average"=7.448, "is_ambiguous"=0, "evidence_score"=3.51846666666666649e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=1;
UPDATE "recommendations" SET "tmdb_id"=591538, "imdb_id"='tt10095582', "igdb_id"=NULL, "title"='The Tragedy of Macbeth', "original_title"='The Tragedy of Macbeth', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/tDNJEhcLbX3jIk3BMCur9pCdaVD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lMjY6kMBOHhloz2Ul16fLJn8xuw.jpg', "overview"='Macbeth, the Thane of Glamis, receives a prophecy from a trio of witches that one day he will become King of Scotland. Consumed by ambition and spurred to action by his wife, Macbeth murders his king and takes the throne for himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.66, "vote_average"=6.918, "is_ambiguous"=0, "evidence_score"=1.32257142857142859e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3;
UPDATE "recommendations" SET "tmdb_id"=120, "imdb_id"='tt0120737', "igdb_id"=NULL, "title"='The Lord of the Rings: The Fellowship of the Ring', "original_title"='The Lord of the Rings: The Fellowship of the Ring', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mWDdRXTivGE7aaY2vo1Ie0PfCX5.jpg', "overview"='Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', "external_url"=NULL, "platforms"=NULL, "popularity"=44.0875, "vote_average"=8.4, "is_ambiguous"=0, "evidence_score"=4.42366666666666645e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=5;
