UPDATE "recommendations" SET "tmdb_id"=9880, "imdb_id"='tt0247638', "igdb_id"=NULL, "title"='The Princess Diaries', "original_title"='The Princess Diaries', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/7axhsbEzFan6HQQ1aMOy7w3CFRx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ktPixrzD9Rbet7Co4uUWxyR9191.jpg', "overview"='A socially awkward but very bright 15-year-old girl being raised by a single mom discovers that she is the princess of a small European country because of the recent death of her long-absent father, who, unknown to her, was the crown prince of Genovia. She must make a choice between continuing the life of a San Francisco teen or stepping up to the throne.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.4369, "vote_average"=6.96, "is_ambiguous"=0, "evidence_score"=1.21833333333333335e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=310;
UPDATE "recommendations" SET "tmdb_id"=6479, "imdb_id"='tt0480249', "igdb_id"=NULL, "title"='I Am Legend', "original_title"='I Am Legend', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/iPDkaSdKk2jRLTM65UOEoKtsIZ8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ePgD1cwmklyrFBjl6z96IuixuSY.jpg', "overview"='Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.9851, "vote_average"=7.218, "is_ambiguous"=0, "evidence_score"=1.5341666666666665e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=312;
