UPDATE "recommendations" SET "tmdb_id"=79707, "imdb_id"='tt1839494', "igdb_id"=NULL, "title"='Children Who Chase Lost Voices', "original_title"='星を追う子ども', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/8RE7Zz9oTzOeMcahqm74AWkOVpV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gB8eFFUw6UA97A7TzrNVrc3D08o.jpg', "overview"='The film centers on Asuna, a young girl who spends her solitary days listening to the mysterious music emanating from the crystal radio she received from her late father as a memento. One day while walking home she is attacked by a fearsome monster and saved by a mysterious boy named Shun. However, Shun disappears and Asuna embarks on a journey of adventure to the land of Agartha with her teacher Mr. Morisaki to meet a Shun again. Through her journey she comes to know the cruelty and beauty of the world, as well as loss.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6707, "vote_average"=7.251, "is_ambiguous"=0, "evidence_score"=6.02333333333333342e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=1263;
