UPDATE "recommendations" SET "tmdb_id"=8512, "imdb_id"='tt0112857', "igdb_id"=NULL, "title"='Devil in a Blue Dress', "original_title"='Devil in a Blue Dress', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/yZ9vNEKOkd0GWWozsopW3SqflYQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/n6SFCz0OsyZ800ZSlaD5WpNmqCj.jpg', "overview"='In late 1940s Los Angeles, Easy Rawlins is an unemployed black World War II veteran with few job prospects. At a bar, Easy meets DeWitt Albright, a mysterious white man looking for someone to investigate the disappearance of a missing white woman named Daphne Monet, who he suspects is hiding out in one of the city''s black jazz clubs. Strapped for money and facing house payments, Easy takes the job, but soon finds himself in over his head.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7407, "vote_average"=6.448, "is_ambiguous"=0, "evidence_score"=6.02, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=1904;
