UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=26192, "title"='The Last of Us Part II', "original_title"='The Last of Us Part II', "media_type"='game', "release_year"=2020, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co5ziw.jpg', "backdrop_url"=NULL, "overview"='The Last of Us Part II is an action-adventure game set five years after the events of The Last of Us. The player traverses post-apocalyptic environments such as buildings and forests to advance the story. They can use firearms, improvised weapons, and stealth to defend against hostile humans and cannibalistic creatures infected by a mutated strain of the Cordyceps fungus. The game intermittently switches control between Ellie and Abby, and also briefly Joel in the opening sequence. The nimble nature of the player character introduces platforming elements, allowing the player to jump and climb to traverse environments and gain advantages during combat.', "external_url"='https://www.igdb.com/games/the-last-of-us-part-ii', "platforms"='["PlayStation 4", "PlayStation 5"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=10.56, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=2184;
