UPDATE "recommendations" SET "tmdb_id"=10442, "imdb_id"='tt0108174', "igdb_id"=NULL, "title"='So I Married an Axe Murderer', "original_title"='So I Married an Axe Murderer', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/zQlpQDKDADKlgqfMs1E191ofDJU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/iVweNwFhEtlJlPxOkaDh8VboE9b.jpg', "overview"='Just after a bad breakup, Charlie MacKenzie falls for lovely butcher Harriet Michaels and introduces her to his parents. But, as voracious consumers of sensational tabloids, his parents soon come to suspect that Harriet is actually a notorious serial killer -- "Mrs. X" -- wanted in connection with a string of bizarre honeymoon killings. Thinking his parents foolish, Charlie proposes to Harriet. But while on his honeymoon with her, he begins to fear they were right.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.3217, "vote_average"=6.113, "is_ambiguous"=0, "evidence_score"=12.312, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 02:46:38' WHERE "id"=2255;
