UPDATE "recommendations" SET "tmdb_id"=9266, "imdb_id"='tt0300532', "igdb_id"=NULL, "title"='Blue Crush', "original_title"='Blue Crush', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xsVMKdSndUKid3Xm3Tudf5bcOlv.jpg', "overview"='Nothing gets between Anne Marie and her board. Living in a beach shack with three roommates, she is up before dawn every morning to conquer the waves and count the days until the Pipe Masters competition. Having transplanted herself to Hawaii with no one''s blessing but her own, Anne Marie finds all she needs in the adrenaline-charged surf scene - until pro quarterback Matt Tollman comes along...', "external_url"=NULL, "platforms"=NULL, "popularity"=3.495, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=1.8816470588235294e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3451;
UPDATE "recommendations" SET "tmdb_id"=21, "imdb_id"='tt0060371', "igdb_id"=NULL, "title"='The Endless Summer', "original_title"='The Endless Summer', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/jDdntrv2j64KB0Zpr63cko4Mebt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uNRfK14Ga8Hwfqt07vo8nvWQN1i.jpg', "overview"='Bruce Brown''s The Endless Summer is one of the first and most influential surf movies of all time. The film documents American surfers Mike Hynson and Robert August as they travel the world during California’s winter (which, back in 1965 was off-season for surfing) in search of the perfect wave and ultimately, an endless summer.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9125, "vote_average"=7.162, "is_ambiguous"=0, "evidence_score"=8.834, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3454;
UPDATE "recommendations" SET "tmdb_id"=9870, "imdb_id"='tt0800039', "igdb_id"=NULL, "title"='Forgetting Sarah Marshall', "original_title"='Forgetting Sarah Marshall', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/d4elOzyhNWVlxpG7BwigrumkFTe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/s39aQY3dK1s6ARrUKP5yeq824nR.jpg', "overview"='When actress Sarah Marshall dumps aspiring musician Peter Bretter for rock star Aldous Snow, Peter''s world comes crashing down. His best friend Brian suggests that Peter should get away from everything and to fly off to Hawaii to escape all his problems. After arriving in Hawaii and meeting the beautiful receptionist Rachel Jansen, Peter is shocked to see not only Aldous in Hawaii, but also Sarah.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0411, "vote_average"=6.507, "is_ambiguous"=0, "evidence_score"=1.47141666666666655e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3462;
