UPDATE "recommendations" SET "tmdb_id"=2770, "imdb_id"='tt0252866', "igdb_id"=NULL, "title"='American Pie 2', "original_title"='American Pie 2', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/854ZZxXdeabAs90mrV72NqShJqR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/as3gvp4DIXVRlXsj5x7OWPQI5lI.jpg', "overview"='After a year apart - attending different schools, meeting different people - the guys rent a beach house and vow to make this the best summer ever. As it turns out, whether that will happen or not has a lot to do with the girls. Between the wild parties, outrageous revelations and yes, a trip to band camp, they discover that times change and people change, but in the end, it''s all about sticking together.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8215, "vote_average"=6.263, "is_ambiguous"=0, "evidence_score"=11.135, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3478;
UPDATE "recommendations" SET "tmdb_id"=10276, "imdb_id"='tt0103241', "igdb_id"=NULL, "title"='What About Bob?', "original_title"='What About Bob?', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/pFCrGGGhV5xeAdvEysv6aSv8T13.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2Ek1JtggvRquMfzie66ybbID9g0.jpg', "overview"='Before going on vacation, self-involved psychiatrist Dr. Leo Marvin has the misfortune of taking on a new patient: Bob Wiley. An exemplar of neediness and a compendium of phobias, Bob follows Marvin to his family''s country house. Dr. Marvin tries to get him to leave; the trouble is, everyone loves Bob. As his oblivious patient makes himself at home, Dr. Marvin loses his professional composure and, before long, may be ready for the loony bin himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4698, "vote_average"=6.885, "is_ambiguous"=0, "evidence_score"=11.05, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3482;
