UPDATE "recommendations" SET "tmdb_id"=10591, "imdb_id"='tt0265208', "igdb_id"=NULL, "title"='The Girl Next Door', "original_title"='The Girl Next Door', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/5mVyFHSY2rSsNgD4NfEwV82HigU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qvcOovScPoRalRxDy50rYSYFree.jpg', "overview"='Exceptionally ambitious high schooler Matthew has aspirations for a career in politics when he falls in love with his gorgeous 19-year-old neighbor, Danielle. But Matthew''s bright future is jeopardized when he finds Danielle was once a porn star. As Danielle''s past catches up with her, Matthew''s love for her forces him to re-evaluate his goals.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.6476, "vote_average"=6.752, "is_ambiguous"=0, "evidence_score"=6.26, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3502;
UPDATE "recommendations" SET "tmdb_id"=1588, "imdb_id"='tt0204946', "igdb_id"=NULL, "title"='Bring It On', "original_title"='Bring It On', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/bnVby0qI0dS7YunbShP7mw68HY3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3XpxR3cSQJou79KBQpPCcpZzmhj.jpg', "overview"='The Toro cheerleading squad from Rancho Carne High School in San Diego has got spirit, spunk, sass and a killer routine that''s sure to land them the national championship trophy for the sixth year in a row. But for newly-elected team captain Torrance, the Toros'' road to total cheer glory takes a shady turn when she discovers that their perfectly-choreographed routines were in fact stolen.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0324, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=11.4325, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3503;
UPDATE "recommendations" SET "tmdb_id"=10314, "imdb_id"='tt0160862', "igdb_id"=NULL, "title"='She''s All That', "original_title"='She''s All That', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/a0pepZNFCjggc7Na9gEwbTI1f46.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oSY7vsYlScliVKomRNviGuWXykC.jpg', "overview"='High school hotshot Zach Siler is the envy of his peers. But his popularity declines sharply when his cheerleader girlfriend, Taylor, leaves him for sleazy reality-television star Brock Hudson. Desperate to revive his fading reputation, Siler agrees to a seemingly impossible challenge. He has six weeks to gain the trust of nerdy outcast Laney Boggs -- and help her to become the school''s next prom queen.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.59, "vote_average"=6.338, "is_ambiguous"=0, "evidence_score"=2.46688888888888868e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3506;
UPDATE "recommendations" SET "tmdb_id"=14191, "imdb_id"='tt0429591', "igdb_id"=NULL, "title"='Aquamarine', "original_title"='Aquamarine', "media_type"='movie', "release_year"=2006, "poster_url"='https://image.tmdb.org/t/p/w500/8mioUyXqn60cwSoLrRCaO5ZAsCV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dysXmAJJNttAXqVWsKJis9MOf17.jpg', "overview"='Two teenage girls discover that mermaids really do exist after a violent storm washes one ashore. The mermaid, a sassy creature named Aquamarine, is determined to prove to her father that real love exists, and enlists the girls'' help in winning the heart of a handsome lifeguard.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.2251, "vote_average"=6.473, "is_ambiguous"=0, "evidence_score"=3.09668965517241403e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3507;
UPDATE "recommendations" SET "tmdb_id"=12620, "imdb_id"='tt0852713', "igdb_id"=NULL, "title"='The House Bunny', "original_title"='The House Bunny', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/4oGGJ824vqIqDtyMvMuK44pDEmx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vz6iY1MtETWRtZMn379JYZGVCX1.jpg', "overview"='Shelley is living a carefree life until a rival gets her tossed out of the Playboy Mansion. With nowhere to go, fate delivers her to the sorority girls from Zeta Alpha Zeta. Unless they can sign a new pledge class, the seven socially clueless women will lose their house to the scheming girls of Phi Iota Mu. In order to accomplish their goal, they need Shelley to teach them the ways of makeup and men; at the same time, Shelley needs some of what the Zetas have - a sense of individuality. The combination leads all the girls to learn how to stop pretending and start being themselves.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.5118, "vote_average"=5.681, "is_ambiguous"=0, "evidence_score"=1.01177777777777784e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 02:46:38' WHERE "id"=3508;
