UPDATE "recommendations" SET "tmdb_id"=40440, "imdb_id"='tt0075244', "igdb_id"=NULL, "title"='Led Zeppelin - The Song Remains the Same', "original_title"='Led Zeppelin - The Song Remains the Same', "media_type"='movie', "release_year"=1976, "poster_url"='https://image.tmdb.org/t/p/w500/tQzNsYcg4rVXVGw45ue7nkdMOgs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cQZrNORK4JHi0ljkHQgU9fO36cU.jpg', "overview"='The best of Led Zeppelin''s legendary 1973 appearances at Madison Square Garden. Interspersed throughout the concert footage are behind-the-scenes moments with the band. The Song Remains the Same is Led Zeppelin at Madison Square Garden in NYC concert footage colorfully enhanced by sequences which are supposed to reflect each band member''s individual fantasies and hallucinations. Includes blistering live renditions of "Black Dog," "Dazed and Confused," "Stairway to Heaven," "Whole Lotta Love," "The Song Remains the Same," and "Rain Song" among others.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.811, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=3.0166666666666666e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 02:46:38' WHERE "id"=5226;
