UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=19562, "title"='Resident Evil 7: Biohazard', "original_title"='Resident Evil 7: Biohazard', "media_type"='game', "release_year"=2017, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/cobtwh.jpg', "backdrop_url"=NULL, "overview"='Resident Evil 7: Biohazard is the first game of the Resident Evil series to switch from 3rd-person to fully 1st-person perspective. A complete refresh of gameplay systems simultaneously propels the survival horror experience to another level. It is as much horror as it is survival, boosting up scare elements and minimizing downright shooting action. The game allows use of Sony''s PSVR Headset to play in VR mode.', "external_url"='https://www.igdb.com/games/resident-evil-7-biohazard', "platforms"='["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PlayStation VR", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=3.01333333333333319e+00, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-11 02:46:38' WHERE "id"=5658;
