UPDATE "recommendations" SET "tmdb_id"=10161, "imdb_id"='tt0097937', "igdb_id"=NULL, "title"='My Left Foot: The Story of Christy Brown', "original_title"='My Left Foot: The Story of Christy Brown', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/GRAAl0bMQFoFIjV3aunc5jsM5u.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zjKg04EquTcnVZUfjHboXnXzjcF.jpg', "overview"='No one expects much from Christy Brown, a boy with cerebral palsy born into a working-class Irish family. Though Christy is a spastic quadriplegic and essentially paralyzed, a miraculous event occurs when, at the age of 5, he demonstrates control of his left foot by using chalk to scrawl a word on the floor. With the help of his steely mother — and no shortage of grit and determination — Christy overcomes his infirmity to become a painter, poet and author.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.9385, "vote_average"=7.53, "is_ambiguous"=0, "evidence_score"=6.18, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-11 02:46:38' WHERE "id"=6686;
