UPDATE "recommendations" SET "tmdb_id"=1394, "imdb_id"='tt0086022', "igdb_id"=NULL, "title"='Nostalgia', "original_title"='Ностальгия', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/fCYSidPXp3LpDa9wlLNv0gZvjyF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/z0ZAEC2aZuflzua3HOSygVzE6Jq.jpg', "overview"='Russian poet Andrei Gorchakov journeys through Italy with his interpreter Eugenia to research the life of an 18th-century Russian composer who once lived abroad. Isolated and consumed by an unrelenting longing for his homeland, Andrei becomes drawn to Domenico, a radical mystic obsessed with spiritual redemption. Through austere imagery and extended temporal rhythms, Tarkovsky examines exile, memory, and the profound melancholy of being unable to belong fully to either place or language.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.489, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=5.032, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-11 02:46:38' WHERE "id"=6857;
