UPDATE "recommendations" SET "tmdb_id"=46195, "imdb_id"='tt1436562', "igdb_id"=NULL, "title"='Rio', "original_title"='Rio', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3vxlXdwBKztOJdgiZ2Qwasl9FY4.jpg', "overview"='Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.', "external_url"=NULL, "platforms"=NULL, "popularity"=15.6785, "vote_average"=6.771, "is_ambiguous"=0, "evidence_score"=5.84666666666666667e+00, "created_at"='2026-08-08 02:23:49', "updated_at"='2026-08-11 02:46:38' WHERE "id"=8225;
