UPDATE "recommendations" SET "tmdb_id"=237791, "imdb_id"='tt1702014', "igdb_id"=NULL, "title"='The Way He Looks', "original_title"='Hoje Eu Quero Voltar Sozinho', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/2BhhlAYwKvONGW7tr16ZhnD0sym.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/wMDg5cm1xIieCTINQo6drZWIy8n.jpg', "overview"='Leonardo is a blind teenager dealing with an overprotective mother while trying to live a more independent life. To the disappointment of his best friend, Giovana, he plans to go on an exchange program abroad. When Gabriel, a new student in town, arrives at their classroom, new feelings blossom in Leonardo making him question his plans.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.2366, "vote_average"=7.926, "is_ambiguous"=0, "evidence_score"=9.69333333333333335e+00, "created_at"='2026-08-08 02:23:49', "updated_at"='2026-08-11 02:46:38' WHERE "id"=8229;
UPDATE "recommendations" SET "tmdb_id"=310569, "imdb_id"='tt3742378', "igdb_id"=NULL, "title"='The Second Mother', "original_title"='Que Horas Ela Volta?', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/u1tDQun2iJAzersd94S8P47WEOL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9h5BsxRmxLAvASADo2VcTlTUdb0.jpg', "overview"='After leaving her daughter Jessica in a small town in Pernambuco to be raised by relatives, Val spends the next 13 years working as a nanny to Fabinho in São Paulo. She has financial stability but has to live with the guilt of having not raised Jessica herself. As Fabinho’s university entrance exams approach, Jessica reappears in her life and seems to want to give her mother a second chance. However, Jessica has not been raised to be a servant and her very existence will turn Val’s routine on its head. With precision and humour, the subtle and powerful forces that keep rigid class structures in place and how the youth may just be the ones to shake it all up.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6688, "vote_average"=8.018, "is_ambiguous"=0, "evidence_score"=3.02, "created_at"='2026-08-08 02:23:49', "updated_at"='2026-08-11 02:46:38' WHERE "id"=8231;
UPDATE "recommendations" SET "tmdb_id"=211166, "imdb_id"='tt1456606', "igdb_id"=NULL, "title"='Rio, I Love You', "original_title"='Rio, Eu Te Amo', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/e4MEGQlEE7VojlBpwaJvjMcXJPg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fee4Wfz9zWhRO7ybfUMIYSCZg8q.jpg', "overview"='The third episode of the Cities of Love franchise, Rio, I Love You is an anthology, created by 10 visionary directors from across the globe. The story line of each segment focuses on an encounter of love in a different neighborhood of the city, demonstrating the distinctive qualities and character of that location. The film serves to bridge gaps between cultures, educating and entertaining the audience, while celebrating unique and universal expressions of love.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4382, "vote_average"=4.796, "is_ambiguous"=0, "evidence_score"=6.02, "created_at"='2026-08-08 02:23:49', "updated_at"='2026-08-11 02:46:38' WHERE "id"=8237;
